V runAgentVisionSmoke(const V& syntheticCommands,const AgentBenchmarkConfig& config,bool live,const std::string& screenshotPath){
    if(live&&config.offlineTransport)throw std::runtime_error("Live vision cannot use an offline test transport");validateAssistantConfig(config.assistant);if(!config.deadlineSeconds)throw std::runtime_error("Vision smoke requires a host deadline");
    AgentSession session;session.suppressIterationHistory();apply(session,syntheticCommands);const auto initialRevision=session.revision;
    V tools=V::makeArr();for(auto tool:AgentSession::tools().arr)if(word(tool,"name")=="snapshot"){tool.set("inputSchema",json(R"({"type":"object","properties":{"view":{"type":"string","enum":["iso","front","right","top"]}},"additionalProperties":false})"));tools.arr.push_back(tool);}
    V captures=V::makeArr();std::atomic_bool cancel=false;std::mutex mutex;std::condition_variable cv;bool finished=false,timedOut=false,completed=false;AssistantUsage usage;AssistantPerformance performance;std::string reply,failure;
    const auto start=Clock::now();std::thread watchdog([&]{std::unique_lock lock(mutex);if(!cv.wait_for(lock,std::chrono::seconds(config.deadlineSeconds),[&]{return finished;})){timedOut=true;cancel=true;}});
    auto stage=std::make_shared<unsigned>(0);AssistantTransport offline=[stage](const auto&,const V&,const auto*){if(++*stage==1)return offlineCall(1,"snapshot",json(R"({"view":"iso"})"));return json(R"({"status":"completed","output":[{"type":"message","role":"assistant","content":[{"type":"output_text","text":"Offline image transport harness complete; no visual understanding was evaluated."}]}]})");};
    auto assistant=config.assistant;assistant.maxRounds=0;if(!live)assistant.protocol=AssistantProtocol::Responses;
    try{auto result=runAssistant(assistant,V::makeStr("Use snapshot to inspect the current synthetic CAD drawing. Describe the visible mechanism, its shapes and connection features, including visible loops and holes, using the actual image. You may request isometric, front, right or top views. Do not edit the drawing. State uncertainty; do not infer loads, manufacturing qualification or hidden parts from the image."),tools,[&](const std::string& name,const V& args){if(name!="snapshot")throw std::runtime_error("Vision smoke permits snapshot only");V safe=V::makeObj();safe.set("view",args.find("view")?*args.find("view"):V::makeStr("iso"));safe.set("expected_revision",V::makeNum(session.revision));safe.set("inline_image",V::makeBool(true));if(!screenshotPath.empty())safe.set("path",V::makeStr(screenshotPath));auto response=session.call("snapshot",safe);V receipt=V::makeObj();receipt.set("is_error",V::makeBool(error(response)));if(auto data=response.find("structuredContent"))receipt.set("metadata",*data);std::size_t encoded=0,bytes=0;if(auto content=response.find("content"))for(const auto& item:content->arr)if(item.find("type")&&item.find("type")->str=="image"){const auto& image=need(item,"data").str;encoded+=image.size();std::size_t padding=0;if(!image.empty()&&image.back()=='=')++padding;if(image.size()>1&&image[image.size()-2]=='=')++padding;bytes+=image.size()/4*3-padding;}receipt.set("png_bytes",V::makeNum(bytes));receipt.set("base64_bytes",V::makeNum(encoded));captures.arr.push_back(receipt);return response;},[&](const AssistantEvent& event){if(event.kind==AssistantEvent::Usage||event.kind==AssistantEvent::ToolEnd){usage=event.usage;performance=event.performance;}},&cancel,live?AssistantTransport{}:config.offlineTransport?config.offlineTransport:offline);reply=result.text;usage=result.usage;performance=result.performance;completed=true;}catch(const std::exception& e){failure=e.what();}
    {std::lock_guard lock(mutex);finished=true;}cv.notify_all();watchdog.join();
    bool pixels=std::any_of(captures.arr.begin(),captures.arr.end(),[](const V& row){return need(row,"png_bytes").num>0;});V result=V::makeObj();result.set("type",V::makeStr("vision_delivery_smoke"));result.set("fixture",V::makeStr("synthetic-pneumatic-cylinder-v1; type withheld from model prompt"));result.set("provider",V::makeStr(config.assistant.provider));result.set("model",V::makeStr(config.assistant.model));result.set("transport",V::makeStr(live?"live_provider":"offline_scripted_harness"));result.set("completed",V::makeBool(completed&&!timedOut));result.set("timed_out",V::makeBool(timedOut));result.set("pixels_in_completed_provider_turn",V::makeBool(live&&completed&&!timedOut&&pixels&&performance.providerRequests>=2));result.set("captures",captures);result.set("reply",V::makeStr(reply));result.set("error",V::makeStr(failure));result.set("usage",usageJson(usage));result.set("performance",performanceJson(performance));result.set("elapsed_ms",V::makeNum((double)ms(start)));result.set("document_unchanged",V::makeBool(session.revision==initialRevision));result.set("human_visual_review",V::makeStr("pending; pixel delivery alone does not prove recognition or design quality"));result.set("cost",V{});return result;
}
AgentBenchmarkSuite parseAgentBenchmarkSuite(const V& value){AgentBenchmarkSuite suite;suite.id=word(value,"id");suite.version=positive(value,"version",1);const auto& cases=need(value,"cases");if(cases.t!=V::Arr||cases.arr.empty())throw std::runtime_error("Benchmark cases must be a nonempty array");std::set<std::string> ids;for(const auto& row:cases.arr){AgentBenchmarkCase test;test.id=word(row,"id");if(!ids.insert(test.id).second)throw std::runtime_error("Duplicate benchmark case");test.version=positive(row,"version",1);test.category=word(row,"category");test.brief=word(row,"brief");test.baseline=need(row,"baseline");test.reference=need(row,"reference");test.checks=need(row,"checks");if(test.baseline.t!=V::Arr||test.reference.t!=V::Arr||test.reference.arr.empty()||test.checks.t!=V::Arr||test.checks.arr.empty())throw std::runtime_error("Invalid benchmark baseline/reference/checks");for(const auto& check:test.checks.arr){word(check,"id");const auto& query=need(check,"query");word(query,"tool");word(query,"path");if(need(query,"args").t!=V::Obj)throw std::runtime_error("Invalid benchmark query args");need(check,"equals");if(auto tolerance=check.find("absolute_tolerance"))if(tolerance->t!=V::Num||tolerance->num<0||!std::isfinite(tolerance->num))throw std::runtime_error("Invalid benchmark tolerance");}suite.cases.push_back(test);}return suite;}
AgentBenchmarkConfig parseAgentBenchmarkConfig(const V& value){AgentBenchmarkConfig config;const auto& assistant=need(value,"assistant");config.assistant.provider=word(assistant,"provider");config.assistant.model=word(assistant,"model");config.assistant.endpoint=word(assistant,"endpoint");config.assistant.apiKeyEnv=need(assistant,"api_key_env").asStr();auto protocol=word(assistant,"protocol");if(protocol=="responses")config.assistant.protocol=AssistantProtocol::Responses;else if(protocol=="chat_completions")config.assistant.protocol=AssistantProtocol::ChatCompletions;else if(protocol=="messages")config.assistant.protocol=AssistantProtocol::Messages;else if(protocol=="claude_code"){config.assistant.protocol=AssistantProtocol::ClaudeCode;config.assistant.authMode=AssistantAuthMode::CliAccount;config.assistant.imageInputSupported=false;}else throw std::runtime_error("Unknown benchmark protocol");if(auto effort=assistant.find("reasoning_effort"))config.assistant.reasoningEffort=effort->asStr();config.assistant.timeoutSeconds=positive(assistant,"timeout_seconds",90);config.repetitions=positive(value,"repetitions",3);config.deadlineSeconds=positive(value,"deadline_seconds",120);if(auto strategies=value.find("strategies")){if(strategies->t!=V::Arr||strategies->arr.empty())throw std::runtime_error("Invalid benchmark strategies");config.strategies.clear();for(const auto& s:strategies->arr){if(s.str!="Single"&&s.str!="Focused"&&s.str!="Parallel")throw std::runtime_error("Unknown benchmark strategy");if(std::find(config.strategies.begin(),config.strategies.end(),s.str)!=config.strategies.end())throw std::runtime_error("Duplicate benchmark strategy");config.strategies.push_back(s.str);}}validateAssistantConfig(config.assistant);return config;}
V preflightAgentBenchmark(const AgentBenchmarkSuite& suite){V report=V::makeObj(),rows=V::makeArr();for(const auto& test:suite.cases){V row=V::makeObj();row.set("case",V::makeStr(test.id));AgentSession session;session.suppressIterationHistory();try{if(!test.baseline.arr.empty())apply(session,test.baseline);apply(session,test.reference);auto checks=inspect(session,test.checks);row.set("checks",checks);row.set("passed",V::makeBool(allPassed(checks)));}catch(const std::exception& e){row.set("error",V::makeStr(e.what()));row.set("passed",V::makeBool(false));}rows.arr.push_back(row);}report.set("passed",V::makeBool(allPassed(rows)));report.set("cases",rows);report.set("suite",V::makeStr(suite.id));report.set("type",V::makeStr("native_reference_preflight"));return report;}
V runAgentBenchmark(const AgentBenchmarkSuite& suite,const AgentBenchmarkConfig& config,bool live,const std::function<void(const V&)>& receipt){if(live&&config.offlineTransport)throw std::runtime_error("Live benchmark cannot use an offline test transport");std::set<std::string> uniqueStrategies;for(const auto& strategy:config.strategies)if((strategy!="Single"&&strategy!="Focused"&&strategy!="Parallel")||!uniqueStrategies.insert(strategy).second)throw std::runtime_error("Invalid or duplicate benchmark strategy");if(config.strategies.empty())throw std::runtime_error("No benchmark strategy selected");validateAssistantConfig(config.assistant);if(config.assistant.model.empty()||!config.repetitions||!config.deadlineSeconds)throw std::runtime_error("Benchmark requires explicit model/repetitions/deadline");for(const auto& id:config.caseIds)if(std::none_of(suite.cases.begin(),suite.cases.end(),[&](const auto& c){return c.id==id;}))throw std::runtime_error("Unknown benchmark case: "+id);V result=V::makeObj(),attempts=V::makeArr();unsigned accepted=0;for(unsigned rep=1;rep<=config.repetitions;++rep)for(const auto& test:suite.cases){if(!config.caseIds.empty()&&std::find(config.caseIds.begin(),config.caseIds.end(),test.id)==config.caseIds.end())continue;for(unsigned offset=0;offset<config.strategies.size();++offset){const auto& strategy=config.strategies[(offset+rep-1)%config.strategies.size()];if(strategy!="Single"&&strategy!="Focused"&&strategy!="Parallel")throw std::runtime_error("Unknown benchmark strategy");auto row=attempt(suite,test,config,strategy,rep,live);if(need(row,"accepted").b)++accepted;if(receipt)receipt(row);attempts.arr.push_back(std::move(row));}}result.set("type",V::makeStr("benchmark_summary"));result.set("strategy_totals",strategyTotals(attempts));result.set("attempts",attempts);result.set("attempt_count",V::makeNum(attempts.arr.size()));result.set("accepted_count",V::makeNum(accepted));result.set("failed_attempt_count",V::makeNum(attempts.arr.size()-accepted));result.set("live",V::makeBool(live));result.set("scope",V::makeStr(live?"Configured provider, synthetic tasks and native postconditions; blind human design evaluation and manufacture remain pending.":"Offline deterministic harness qualification only; no LLM speed, cost or design-quality conclusion."));return result;}
